<script setup>import{computed,inject,onMounted,ref,watch}from'vue';import{call,__}from'../api';const p=defineProps({resource:String});const{ctx}=inject('portal'),state=ref('loading'),rows=ref([]),search=ref(''),page=ref(1);const map={"import-files":'Vehicle Import File',vehicles:'Vehicle Master',suppliers:'Supplier','purchase-orders':'Purchase Order','purchase-receipts':'Purchase Receipt','purchase-invoices':'Purchase Invoice','supplier-payments':'Payment Entry','landed-costs':'Landed Cost Voucher',customers:'Customer',quotations:'Quotation','sales-orders':'Sales Order','sales-invoices':'Sales Invoice','customer-payments':'Payment Entry',serials:'Serial No',inspections:'Quality Inspection'};const dt=computed(()=>map[p.resource]);async function load(){state.value='loading';try{const filters=(p.resource==='supplier-payments'?{payment_type:'Pay'}:p.resource==='customer-payments'?{payment_type:'Receive'}:{});rows.value=(await call('an_truck_portal.api.records.list_records',{doctype:dt.value,search:search.value,company:ctx.company,page:page.value,filters})).rows;state.value='ready'}catch(e){state.value='error';rows.value=[{error:e.message}]}}onMounted(load);watch(()=>p.resource,()=>{page.value=1;load()});let t;watch(search,()=>{clearTimeout(t);t=setTimeout(load,300)});function link(r){return dt.value==='Vehicle Master'?`/vehicles/${r.name}`:dt.value==='Vehicle Import File'?`/import-files/${r.name}`:`/app/${dt.value.toLowerCase().replaceAll(' ','-')}/${encodeURIComponent(r.name)}`}function open(r){window.location.href=link(r)}</script>
<template><div class="page"><div class="page-head"><div><p class="eyebrow">{{__('Records')}}</p><h1>{{__(dt)}}</h1></div><input class="filter" v-model="search" :placeholder="__('Search…')"></div><div class="panel table-wrap"><div v-if="state==='loading'" class="empty">{{__('Loading…')}}</div><div v-else-if="state==='error'" class="empty error">{{rows[0]?.error}}</div><div v-else-if="!rows.length" class="empty">{{__('No records found')}}</div><table v-else><thead><tr><th v-for="(_,k) in rows[0]">{{__(k.replaceAll('_',' '))}}</th></tr></thead><tbody><tr v-for="r in rows" @click="open(r)"><td v-for="(v,k) in r" :class="{ltr:['name','vin'].includes(k)}"><span v-if="k==='status'||k==='vehicle_status'" class="badge">{{__(v)}}</span><template v-else>{{v??'—'}}</template></td></tr></tbody></table></div></div></template>
